package za.co.gpbrij.cph.api;
import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import za.co.gpbrij.cph.domain.*; import za.co.gpbrij.cph.repository.*; import java.util.*;
@RestController @RequestMapping("/api/v1") public class ReferenceDataController { private final CustomerRepository c; private final BeneficiaryRepository b; private final SanctionEntryRepository s; public ReferenceDataController(CustomerRepository c,BeneficiaryRepository b,SanctionEntryRepository s){this.c=c;this.b=b;this.s=s;} @GetMapping("/customers") List<Customer> customers(){return c.findAll();} @PostMapping("/customers") ResponseEntity<Customer> customer(@RequestBody Customer x){return ResponseEntity.status(201).body(c.save(x));} @GetMapping("/beneficiaries") List<Beneficiary> beneficiaries(){return b.findAll();} @PostMapping("/beneficiaries") ResponseEntity<Beneficiary> beneficiary(@RequestBody Beneficiary x){return ResponseEntity.status(201).body(b.save(x));} @GetMapping("/sanctions") List<SanctionEntry> sanctions(){return s.findAll();} @PostMapping("/sanctions") ResponseEntity<SanctionEntry> sanction(@RequestBody SanctionEntry x){return ResponseEntity.status(201).body(s.save(x));} }
